// Claude's review tests for A37 (streaming replies: chunked fetch bodies and EventSource).
// agy: do not edit this file.
import { expect, test, type Page } from '@playwright/test';
import { emptyState, type Mock, type Project, type WemockState } from '../src/core/types';
import { type FixtureServer, startFixtureServer } from './fixture/server';
import { type WemockSession, launchWemock } from './helpers';

let fixture: FixtureServer;
let session: WemockSession;

test.beforeAll(async () => {
  fixture = await startFixtureServer();
  session = await launchWemock(fixture.url);
});

test.afterAll(async () => {
  await session?.context?.close();
  await fixture?.close();
});

const mk = (id: string, urlPattern: string, extra: Partial<Mock>): Mock => ({
  id, name: id, enabled: true, method: 'ANY', urlPattern, source: 'manual', createdAt: 0,
  response: { status: 200, headers: { 'content-type': 'text/plain' }, body: '', bodyEncoding: 'text', delayMs: 0 }, ...extra,
});

const chat = mk('chat', '/api/chat', { reply: 'stream', stream: { chunks: ['Hello', ', ', 'world'], gapMs: 150, sse: false } });
const events = mk('events', '/api/events', { reply: 'stream', stream: { chunks: ['{"n":1}', 'event: done\nid: 7\ndata: bye'], gapMs: 100, sse: true } });
const plain = mk('plain', '/api/plain', { response: { status: 200, headers: { 'content-type': 'text/plain' }, body: 'just one', bodyEncoding: 'text', delayMs: 0 } });

async function readState(): Promise<WemockState> {
  return session.worker.evaluate(async () => {
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    return (await (globalThis as any).chrome.storage.local.get('wemock.state'))['wemock.state'];
  });
}

async function open(mocks: Mock[]): Promise<{ page: Page; panel: Page }> {
  const p: Project = { id: 'p1', name: 'site', origins: [fixture.origin], activeScenarioId: 'default', scenarios: [{ id: 'default', name: 'Default', mocks }] };
  await session.setState({ ...emptyState(), enabledOrigins: [fixture.origin], projects: [p] });
  const page = await session.context.newPage();
  await page.goto(`${fixture.url}/index.html`);
  const tabId = await session.tabIdOf(page);
  const panel = await session.context.newPage();
  await panel.goto(`chrome-extension://${session.extensionId}/panel.html?tabId=${tabId}`);
  return { page, panel };
}

test('fetch: the body arrives chunk by chunk, gapMs apart; text() waits for all', async () => {
  const { page, panel } = await open([chat]);
  try {
    const got = await page.evaluate(async () => {
      const t0 = performance.now();
      const res = await fetch('/api/chat', { method: 'POST', body: '{"q":"hi"}' });
      const reader = res.body!.getReader();
      const dec = new TextDecoder();
      const parts: { text: string; at: number }[] = [];
      for (;;) {
        const { done, value } = await reader.read();
        if (done) break;
        parts.push({ text: dec.decode(value), at: Math.round(performance.now() - t0) });
      }
      const whole = await (await fetch('/api/chat')).text();
      return { status: res.status, parts, whole };
    });
    expect(got.status).toBe(200);
    expect(got.parts.map((p) => p.text)).toEqual(['Hello', ', ', 'world']);
    expect(got.parts[2]!.at - got.parts[0]!.at).toBeGreaterThanOrEqual(250);
    expect(got.whole).toBe('Hello, world');
    await expect(panel.getByTestId('log-row').filter({ hasText: '/api/chat' }).filter({ hasText: 'MOCK' })).toHaveCount(2);
  } finally {
    await panel.close();
    await page.close();
  }
});

test('fetch: as Server-Sent Events, each chunk is a data: frame, event and id lines kept', async () => {
  const { page, panel } = await open([events]);
  try {
    const got = await page.evaluate(async () => {
      const r = await fetch('/api/events');
      return { type: r.headers.get('content-type'), text: await r.text() };
    });
    expect(got.type).toBe('text/event-stream');
    expect(got.text).toBe('data: {"n":1}\n\nevent: done\nid: 7\ndata: bye\n\n');
  } finally {
    await panel.close();
    await page.close();
  }
});

test('EventSource: open, a message per chunk with its event and id, then closed; instanceof holds', async () => {
  const { page, panel } = await open([events, plain]);
  try {
    const got = await page.evaluate(async () => {
      const es = new EventSource('/api/events');
      const seen: string[] = [];
      es.onopen = () => seen.push(`open ${es.readyState}`);
      es.onmessage = (e) => seen.push(`message ${e.data}`);
      es.addEventListener('done', (e) => seen.push(`done ${(e as MessageEvent).data} id=${(e as MessageEvent).lastEventId}`));
      await new Promise<void>((resolve) => {
        es.onerror = () => {
          seen.push(`error ${es.readyState}`);
          resolve();
        };
      });
      const isEs = es instanceof EventSource;
      const one = new EventSource('/api/plain');
      const plainSeen: string[] = [];
      await new Promise<void>((resolve) => {
        one.onmessage = (e) => plainSeen.push(e.data);
        one.onerror = () => resolve();
      });
      return { seen, isEs, plainSeen };
    });
    expect(got.seen).toEqual(['open 1', 'message {"n":1}', 'done bye id=7', 'error 2']);
    expect(got.isEs).toBe(true);
    expect(got.plainSeen).toEqual(['just one']);
    await expect(panel.getByTestId('log-row').filter({ hasText: '/api/events' }).filter({ hasText: 'MOCK' })).toHaveCount(1);
  } finally {
    await panel.close();
    await page.close();
  }
});

test('EventSource with no mock is the real one', async () => {
  const { page, panel } = await open([]);
  try {
    const native = await page.evaluate(() => {
      const es = new EventSource('/api/nothing');
      const isNative = Object.getPrototypeOf(es) === EventSource.prototype || es.constructor.name === 'EventSource';
      es.close();
      return { isNative, readyState: es.readyState };
    });
    expect(native).toEqual({ isNative: true, readyState: 2 });
  } finally {
    await panel.close();
    await page.close();
  }
});

test('XHR gets the whole streamed body at the end', async () => {
  const { page, panel } = await open([chat]);
  try {
    const text = await page.evaluate(() => new Promise<string>((resolve) => {
      const x = new XMLHttpRequest();
      x.open('GET', '/api/chat');
      x.onload = () => resolve(x.responseText);
      x.send();
    }));
    expect(text).toBe('Hello, world');
  } finally {
    await panel.close();
    await page.close();
  }
});

test('the editor makes a Stream reply', async () => {
  const { page, panel } = await open([plain]);
  try {
    await panel.getByTestId('tab-mocks').click();
    await panel.getByTestId('mock-row').filter({ hasText: 'plain' }).click();
    await panel.getByTestId('reply-stream').click();
    // Starts from the fixed body as one chunk.
    await expect(panel.getByTestId('stream-chunk')).toHaveCount(1);
    await expect(panel.getByTestId('stream-chunk').first()).toHaveValue('just one');
    await panel.getByTestId('stream-chunk-add').click();
    await panel.getByTestId('stream-chunk').nth(1).fill('and two');
    await panel.getByTestId('stream-gap').fill('40');
    await panel.getByTestId('stream-sse').check();
    await panel.getByTestId('mock-save').click();
    await expect.poll(async () => (await readState()).projects[0]!.scenarios[0]!.mocks[0]).toMatchObject({
      reply: 'stream', stream: { chunks: ['just one', 'and two'], gapMs: 40, sse: true },
    });
  } finally {
    await panel.close();
    await page.close();
  }
});
